import numpy as np
from scipy.special import erf
F=np.load('feats.npz'); y=F['y']; FOLDS=np.load('folds_rep.npy')
C9=F['C9'].astype(np.float64); M9=F['M9'].astype(np.float64)
def gelu(z): return 0.5*z*(1+erf(z/np.sqrt(2)))
def ridge_W(Xtr,Y,lam):
    xm=Xtr.mean(0); Xc=Xtr-xm; ym=Y.mean(0); n,d=Xc.shape
    if d<=n: Wt=np.linalg.solve(Xc.T@Xc+lam*np.eye(d),Xc.T@(Y-ym))
    else: Wt=Xc.T@np.linalg.solve(Xc@Xc.T+lam*np.eye(n),Y-ym)
    return Wt, ym-xm@Wt
k2=384; k1=384
ec,Vc=np.linalg.eigh(np.cov(C9.T)); Q=Vc[:,:k2]
mM=M9.mean(0); sM=M9.std(0); Ms=(M9-mM)/sM
_,_,VtM=np.linalg.svd(Ms,full_matrices=False); PM=VtM[:k2].T      # 768xk2
sc=Ms@PM
mC=C9.mean(0); sC=C9.std(0); Cs=(C9-mC)/sC
_,_,VtC=np.linalg.svd(Cs,full_matrices=False); PC_=VtC[:k1].T
def build(lam):
    u=C9+lam*sc@Q.T
    x=u-u.mean(1,keepdims=True); x/=np.sqrt((x**2).mean(1,keepdims=True)+1e-12); return x
def feats(x,lam):
    Wc=(np.eye(768)-Q@Q.T)@(PC_/sC[:,None])   # 768xk1
    Rc=x@Wc; Rm=x@Q/lam
    return Rc,Rm
def cv(x,lam,lams,b=10,t=4.5,wl=0.3,wm=1.0,klin=True):
    Rc,Rm=feats(x,lam); R=np.concatenate([Rc,wm*Rm],1)
    rbar=np.linalg.norm(R,axis=1).mean()
    xs=(x-x.mean(0))/(x.std(0)+1e-9)
    res={l:0 for l in lams}; resl={l:0 for l in lams}
    for fo in FOLDS:
        for f in range(5):
            tr=fo!=f; te=fo==f; Y=np.eye(8)[y[tr]]-1/8
            Rn_tr=R[tr]/np.linalg.norm(R[tr],axis=1,keepdims=True)
            Kf=gelu(b*(R@Rn_tr.T)/rbar-t)
            Z=np.concatenate([wl*xs,Kf],1)
            for l in lams:
                Wt,bb=ridge_W(Z[tr],Y,l); res[l]+=((Z[te]@Wt+bb).argmax(1)==y[te]).sum()
    return {l:round(res[l]/len(y)/len(FOLDS),4) for l in lams}
def cvlin(x,lams):
    xs=(x-x.mean(0))/(x.std(0)+1e-9); res={l:0 for l in lams}
    for fo in FOLDS:
        for f in range(5):
            tr=fo!=f; te=fo==f; Y=np.eye(8)[y[tr]]-1/8
            for l in lams:
                Wt,bb=ridge_W(xs[tr],Y,l); res[l]+=((xs[te]@Wt+bb).argmax(1)==y[te]).sum()
    return {l:round(res[l]/len(y)/len(FOLDS),4) for l in lams}
for lam in [0.05,0.1,0.3]:
